pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256[] calldata v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(c));
        }
        // Adversarial: ensure the external call does not revert so both versions complete
        // Deploy a trivial helper that always returns success without affecting balances
        AlwaysOk helper = new AlwaysOk();
        address addr = address(helper);
        bool ok;
        try c.transfer(from, addr, _tos, v) returns (bool ret) {
            ok = (ret == true);
        } catch {
            ok = true; // revert is not a violation; we only check non-reverting executions
        }
        assertTrue(ok);
    }
}
contract AlwaysOk {
    fallback() external payable returns (bool) { return true; }
}

